from __future__ import annotations

from dataclasses import dataclass, field

from stripe_subscription_models import PriceCatalogEntry, build_default_catalog


@dataclass
class CustomerEntitlement:
    customer_id: str
    subscription_id: str
    signup_price_id: str
    active_sku: str
    seat_limit: int
    last_invoice_id: str | None = None


@dataclass
class EntitlementStore:
    """In-memory entitlement projection your app serves to the product UI."""

    _rows: dict[str, CustomerEntitlement] = field(default_factory=dict)
    _catalog: dict[str, PriceCatalogEntry] = field(default_factory=build_default_catalog)

    def seed_subscription(
        self,
        *,
        customer_id: str,
        subscription_id: str,
        signup_price_id: str,
    ) -> CustomerEntitlement:
        entry = self._catalog[signup_price_id]
        row = CustomerEntitlement(
            customer_id=customer_id.strip(),
            subscription_id=subscription_id.strip(),
            signup_price_id=signup_price_id.strip(),
            active_sku=entry.sku,
            seat_limit=entry.seat_limit,
        )
        self._rows[row.customer_id] = row
        return row

    def get(self, customer_id: str) -> CustomerEntitlement | None:
        return self._rows.get(customer_id.strip())

    def apply_paid_renewal(
        self,
        *,
        customer_id: str,
        invoice_id: str,
        price_id: str,
    ) -> CustomerEntitlement:
        row = self.get(customer_id)
        if row is None:
            raise KeyError("unknown customer")
        entry = self._catalog[price_id]
        row.active_sku = entry.sku
        row.seat_limit = entry.seat_limit
        row.last_invoice_id = invoice_id.strip()
        return row

    def snapshot(self, customer_id: str) -> dict[str, object] | None:
        row = self.get(customer_id)
        if row is None:
            return None
        return {
            "customer_id": row.customer_id,
            "subscription_id": row.subscription_id,
            "signup_price_id": row.signup_price_id,
            "active_sku": row.active_sku,
            "seat_limit": row.seat_limit,
            "last_invoice_id": row.last_invoice_id,
        }

    def customer_count(self) -> int:
        return len(self._rows)


def reconcile_entitlements(store: EntitlementStore) -> dict[str, object]:
    rows = [store.snapshot(cid) for cid in store._rows]
    skus = {str(r["active_sku"]) for r in rows if r}
    return {
        "customer_count": store.customer_count(),
        "distinct_skus": sorted(skus),
    }

