from __future__ import annotations

"""Apply Stripe renewal invoices to the entitlement projection your app reads."""

from entitlement_store import EntitlementStore
from stripe_subscription_models import (
    SubscriptionRenewalInvoice,
    build_default_catalog,
    catalog_sku_for_price,
)


REASON_SYNCED = "entitlements_synced"
REASON_SKIPPED = "renewal_not_applicable"
REASON_UNKNOWN_CUSTOMER = "customer_not_found"


def _price_id_for_entitlement_update(
    invoice: SubscriptionRenewalInvoice,
    store: EntitlementStore,
) -> str:
    row = store.get(invoice.customer_id)
    if row is None:
        return invoice.current_price_id
    return row.signup_price_id


def evaluate_renewal_entitlement_sync(
    invoice: SubscriptionRenewalInvoice,
    store: EntitlementStore,
) -> dict[str, object]:
    if not invoice.is_paid_renewal():
        return {
            "customer_id": invoice.customer_id,
            "subscription_id": invoice.subscription_id,
            "stripe_event_id": invoice.stripe_event_id,
            "entitlements_updated": False,
            "active_sku": None,
            "seat_limit": None,
            "reason": REASON_SKIPPED,
        }

    existing = store.get(invoice.customer_id)
    if existing is None:
        return {
            "customer_id": invoice.customer_id,
            "subscription_id": invoice.subscription_id,
            "stripe_event_id": invoice.stripe_event_id,
            "entitlements_updated": False,
            "active_sku": None,
            "seat_limit": None,
            "reason": REASON_UNKNOWN_CUSTOMER,
        }

    catalog = build_default_catalog()
    price_id = _price_id_for_entitlement_update(invoice, store)
    sku = catalog_sku_for_price(catalog, price_id)
    entry = catalog[price_id]
    store.apply_paid_renewal(
        customer_id=invoice.customer_id,
        invoice_id=invoice.invoice_id,
        price_id=price_id,
    )
    snap = store.snapshot(invoice.customer_id) or {}

    return {
        "customer_id": invoice.customer_id,
        "subscription_id": invoice.subscription_id,
        "stripe_event_id": invoice.stripe_event_id,
        "entitlements_updated": True,
        "active_sku": snap.get("active_sku", sku),
        "seat_limit": snap.get("seat_limit", entry.seat_limit),
        "reason": REASON_SYNCED,
    }


def summarize_renewal_syncs(results: list[dict[str, object]]) -> dict[str, object]:
    synced = sum(1 for row in results if row.get("entitlements_updated"))
    skipped = sum(1 for row in results if row.get("reason") == REASON_SKIPPED)
    missing = sum(1 for row in results if row.get("reason") == REASON_UNKNOWN_CUSTOMER)
    return {
        "events_evaluated": len(results),
        "synced_count": synced,
        "skipped_count": skipped,
        "missing_customer_count": missing,
        "results": results,
    }


class RenewalEntitlementWorkflow:
    def __init__(self, store: EntitlementStore | None = None) -> None:
        self._store = store if store is not None else EntitlementStore()
        self._history: list[dict[str, object]] = []

    @property
    def store(self) -> EntitlementStore:
        return self._store

    def handle(self, invoice: SubscriptionRenewalInvoice) -> dict[str, object]:
        outcome = evaluate_renewal_entitlement_sync(invoice, self._store)
        self._history.append(outcome)
        return outcome

    def summarize(self) -> dict[str, object]:
        return summarize_renewal_syncs(self._history)


def workflow_health(workflow: RenewalEntitlementWorkflow) -> str:
    summary = workflow.summarize()
    if summary["missing_customer_count"]:
        return "data_gap"
    if summary["synced_count"]:
        return "healthy"
    return "idle"

